import{K as r,a as i,c as l,b as a,k as n,q as s,ac as c}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"PowerPoint 图片、图形与流程图排版","description":"插入裁剪图片，使用选择窗格、对齐、分布、组合与连接符绘制流程图，处理层级、图标、替代文字和阅读顺序。","frontmatter":{"title":"PowerPoint 图片、图形与流程图排版","description":"插入裁剪图片，使用选择窗格、对齐、分布、组合与连接符绘制流程图，处理层级、图标、替代文字和阅读顺序。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · PowerPoint 演示制作","summary":"插入裁剪图片，使用选择窗格、对齐、分布、组合与连接符绘制流程图，处理层级、图标、替代文字和阅读顺序。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":{"text":"PowerPoint 主题、母版与版式","link":"/tools/office/powerpoint/layout"},"next":{"text":"PowerPoint 表格、图表与 Excel 数据关联","link":"/tools/office/powerpoint/data"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"PowerPoint 主题、母版与版式","link":"/tools/office/powerpoint/layout"},"next":{"text":"PowerPoint 表格、图表与 Excel 数据关联","link":"/tools/office/powerpoint/data"}},"headers":[],"relativePath":"tools/office/powerpoint/graphics.md","filePath":"tools/office/powerpoint/graphics.md"}'),h={name:"tools/office/powerpoint/graphics.md"},g=Object.assign(h,{setup(p){const o={path:"/tools/office/powerpoint/graphics",app:"PowerPoint",title:"用形状画一个整齐的四步流程",steps:[{tab:"插入",command:"形状",setting:"四个矩形：录入 / 检查 / 汇总 / 交付",anchor:"walkthrough-1"},{tab:"形状格式",command:"对齐",setting:"垂直居中；横向分布；对象：四个矩形",anchor:"walkthrough-2"},{tab:"插入",command:"形状 / 连接符",setting:"连接相邻步骤；移动后检查端点",anchor:"walkthrough-3"}]};return(d,e)=>{const t=r("OfficeGuide");return i(),l("div",null,[e[0]||(e[0]=a("h1",{id:"powerpoint-图片、图形与流程图排版",tabindex:"-1"},[n("PowerPoint 图片、图形与流程图排版 "),a("a",{class:"header-anchor",href:"#powerpoint-图片、图形与流程图排版","aria-label":'Permalink to "PowerPoint 图片、图形与流程图排版"'},"​")],-1)),e[1]||(e[1]=a("p",null,"图形应该表达关系，图片应该提供信息或必要背景。装饰太多会挤压正文和数据的空间。先用简单形状把含义画清楚，再调整颜色和细节。",-1)),s(t,{guide:o}),e[2]||(e[2]=c('<h2 id="images" tabindex="-1">图片处理 <a class="header-anchor" href="#images" aria-label="Permalink to &quot;图片处理 {#images}&quot;">​</a></h2><p>通过“插入 → 图片”选择素材，拖动角点或在大小设置中保持比例。裁剪用来调整构图，不能用拉伸把图片强行填满。若采用裁剪填充，检查人物面部、文字和重要标识没有被切掉。</p><p>截图只保留要解释的区域，必要时加边框或箭头突出目标。不要在截图中留下真实账号、内部地址或无关个人信息；覆盖、裁剪和隐藏不总等于从文件中删除原始数据，外发前检查最终文件中实际保留的内容。</p><p>图片压缩前保留原稿，在最终放映比例下检查细字。图像清晰度、文件大小和可编辑性要按交付目标取舍，不因文件较大就反复压缩到模糊。</p><h2 id="flow" tabindex="-1">画一个四步流程 <a class="header-anchor" href="#flow" aria-label="Permalink to &quot;画一个四步流程 {#flow}&quot;">​</a></h2><p>本篇流程为“收集数据 → 校验规则 → 汇总分析 → 发布月报”。</p><ol><li>插入一个圆角矩形，输入第一步，设置统一字体和尺寸。</li><li>复制出另外三个形状，修改文字，避免四次独立绘制导致尺寸不同。</li><li>多选四个形状，使用对齐和水平分布；确认当前是相对幻灯片还是相对所选对象对齐。</li><li>插入连接符，把端点连接到形状的连接点，再设置箭头方向。</li><li>移动其中一个形状，检查连接符是否跟随；若没有，可能只是普通线条或端点没有真正连接。</li><li>选中整个流程并组合，便于整体移动和缩放。</li></ol><p>分支流程用判断条件标明箭头含义，例如“校验通过/退回修正”，不要让读者靠颜色猜方向。</p><h2 id="layers" tabindex="-1">层级、选择与组合 <a class="header-anchor" href="#layers" aria-label="Permalink to &quot;层级、选择与组合 {#layers}&quot;">​</a></h2><p>通过“选择窗格”查看对象顺序，给关键对象改名，例如“流程-校验”“说明-数据口径”。被遮挡的对象可以从窗格选择，再调整置于顶层/底层。临时隐藏可帮助编辑，但交付前要确认隐藏内容是否仍在文件中。</p><p>组合适合一起移动的元素，取消组合后可单独修改。带文字的复杂组合整体缩放后，应检查文字有没有溢出。不同对象类型并非都能任意组合，遇到无法组合时先检查选中的是否包含占位符等特殊对象。</p><h2 id="smartart" tabindex="-1">SmartArt 与手工图形 <a class="header-anchor" href="#smartart" aria-label="Permalink to &quot;SmartArt 与手工图形 {#smartart}&quot;">​</a></h2><p>层级、循环、流程等规则结构可用 SmartArt 快速建立，但应选择语义相符的布局。为了容纳更多文字不断增加节点，最终可能让文字过小；复杂关系用分步页面或简化后的手工图更清楚。</p><p>组织架构图表达汇报层级，流程图表达步骤，不应只因某个模板好看就混用。图标尽量采用同一套线条和视觉风格，并辅以文字标签，防止含义不明确。</p><h2 id="practice" tabindex="-1">阅读顺序和验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;阅读顺序和验收 {#practice}&quot;">​</a></h2><p>每页保留明确标题，为重要图片添加替代文字。使用辅助功能检查器并按版本提供的阅读顺序工具核对顺序；视觉上从左到右排列，并不保证屏幕阅读器按同样顺序读取。不要只靠红绿颜色区分成功和失败。<a href="https://support.microsoft.com/en-us/accessibility/powerpoint/make-your-powerpoint-presentations-accessible-to-people-with-disabilities" target="_blank" rel="noopener noreferrer">微软演示稿可访问性说明</a></p><p>练习完成四步流程后，调换第二、三步的位置，确认文字、箭头和阅读顺序仍符合含义。最后在放映模式查看，后排观看者应能辨认每一步，而不是只能看见彩色方块。</p><h2 id="walkthrough" tabindex="-1">图示跟做：用形状画一个整齐的四步流程 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：用形状画一个整齐的四步流程 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：先用相同形状建立结构 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：先用相同形状建立结构 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：插入 → 形状。</strong></p><p>插入一个矩形，输入录入，确定字体和填充后用 Ctrl+D 复制三份，分别改成检查、汇总、交付。复制能够保持基础尺寸一致，比每次重新画形状更容易对齐。每个框只放动作词，详细解释放在页面说明或备注。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：把边界与间距同时对齐 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：把边界与间距同时对齐 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：形状格式 → 对齐。</strong></p><p>按住 Shift 逐个选中四个矩形，打开“形状格式 → 对齐”，先垂直居中，再横向分布。检查是相对于所选对象还是幻灯片进行对齐，避免一键把所有框移动到画布中心。先摆好两端位置，再分布中间对象通常更可控。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：用连接符表达顺序 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：用连接符表达顺序 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：插入 → 形状 / 连接符。</strong></p><p>从形状列表选连接符，将端点连接到相邻矩形的连接点。轻微移动一个矩形，观察线段是否仍跟随，悬空的普通线段需要重新连接。确认文字、箭头和顺序都正确后再组合相关对象，避免组合太早增加后续编辑难度。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>图形被盖住时，用选择窗格按名称选择对象并调整层级。组合不能修复错误的阅读顺序；导出 PDF 后还要看线条和文字在实际大小是否清楚。</p>',30))])}}});export{u as __pageData,g as default};
